# Ensure NSID is character for all
# The mapping for merging
full_df <- data_list[[1]] %$% full_join(data_list[[2]], by = 'NSID') %>% 
  full_join(data_list[[3]], by = 'NSID') %>% 
  full_join(data_list[[4]], by = 'NSID') %>% 
