  # We only care if it's a substantive Yes (1) or No (2)
  # For S1-S7, 1=Yes, 2=No. 
  # For S8-S9, 1=Never, 2-5=Drinking

  if (wave %in% c(1, 2, 3, 4, 6, 7)) {
    if (val == 1) return(1)
    if (val == 2) return(0)
    return(NA)
  } else if (wave %in% c(8, 9)) {
    if (val == 1) return(0)
    if (val >= 2 && val <= 5) return(1)
    return(NA)
  }
  return(NA)
}

